-- Introductions, shared literature collections, 63 proposed paper links (35 Bio-Core, 28 Interdisciplinary), three proposed concepts,
-- and the human-example draft stages for bio-core-lpm-synth and interdisciplinary-lpm-synth.
-- Generated by scripts/generate_bio_interdisciplinary_enrichment_seed.py; do not hand-edit.
--
-- Source: lab_manager/docs/design-notes/bio-core-interdisciplinary-modelling-literature-
-- human-examples-and-time-budget-2026-10-25.md (sections 3, 4 and 6). Decisions applied from
-- Dustin, 2026-10-25: never cite the 2020 Eirdosh & Hanisch paper; leave Evolutionary Mismatch
-- out of Bio-Core; load the proposed human cases as drafts.
--
-- Everything below is AI-drafted and has not been reviewed by a subject-matter expert. Stages
-- load as 'draft', threads and concepts as 'proposed', paper links as 'draft'. Every statement
-- is idempotent (fixed uuid5 ids, ON CONFLICT or WHERE NOT EXISTS).

-- 0. Keep the comparison profile accurate: scope and depth count accepted content only, so proposed
-- threads and draft stages do not inflate either space. Draft and proposed counts are added as
-- trailing columns (CREATE OR REPLACE VIEW allows new columns at the end only).
CREATE OR REPLACE VIEW lpm_data_object_richness AS
SELECT
  o.id AS data_object_id,
  o.project_id,
  o.object_type,
  o.title,
  o.grade_band,
  length(coalesce(o.description, '')) AS description_length,
  jsonb_array_length(CASE WHEN jsonb_typeof(o.content -> 'performanceIndicators') = 'array' THEN o.content -> 'performanceIndicators' ELSE '[]'::jsonb END) AS performance_indicator_count,
  jsonb_array_length(CASE WHEN jsonb_typeof(o.content -> 'concepts') = 'array' THEN o.content -> 'concepts' ELSE '[]'::jsonb END) AS concept_link_count,
  (SELECT count(*) FROM curriculum_repository_links l WHERE l.data_object_id = o.id) AS curriculum_repository_link_count,
  (SELECT count(*) FROM lpm_comparative_links c WHERE c.from_data_object_id = o.id OR c.to_data_object_id = o.id) AS comparative_link_count,
  (SELECT count(*) FROM evidence_links e WHERE e.target_type = 'data_object' AND e.target_id = o.id) AS evidence_link_count,
  o.status AS status
FROM lpm_data_objects o;

CREATE OR REPLACE VIEW lpm_project_comparison_profile AS
SELECT
  p.id AS project_id,
  p.slug,
  p.name,
  (SELECT count(*) FROM lpm_threads th WHERE th.project_id = p.id AND th.status = 'accepted') AS strand_count,
  (SELECT count(*) FROM lpm_data_objects o WHERE o.project_id = p.id AND o.object_type = 'substrand' AND o.status = 'accepted') AS substrand_count,
  (SELECT count(DISTINCT o.grade_band) FROM lpm_data_objects o WHERE o.project_id = p.id AND o.status = 'accepted' AND o.grade_band IS NOT NULL) AS grade_bands_covered,
  (SELECT count(DISTINCT d) FROM lpm_data_objects o, jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(o.content -> 'associatedDomains') = 'array' THEN o.content -> 'associatedDomains' ELSE '[]'::jsonb END
    ) AS d WHERE o.project_id = p.id AND o.status = 'accepted') AS subject_domain_count,
  (SELECT round(avg(r.description_length), 0) FROM lpm_data_object_richness r WHERE r.project_id = p.id AND r.status = 'accepted') AS avg_description_length,
  (SELECT round(avg(r.performance_indicator_count), 1) FROM lpm_data_object_richness r WHERE r.project_id = p.id AND r.status = 'accepted') AS avg_performance_indicators,
  (SELECT round(avg(r.curriculum_repository_link_count), 1) FROM lpm_data_object_richness r WHERE r.project_id = p.id AND r.status = 'accepted') AS avg_real_world_links,
  (SELECT count(*) FROM theories th WHERE th.project_id = p.id) AS theory_count,
  (SELECT count(*) FROM literature_references lr WHERE lr.project_id = p.id) AS literature_count,
  (SELECT count(*) FROM curriculum_repository_links l WHERE l.project_id = p.id) AS curriculum_repository_link_count,
  (SELECT count(*) FROM lpm_comparative_links c
     JOIN lpm_data_objects o ON o.id = c.from_data_object_id OR o.id = c.to_data_object_id
     WHERE o.project_id = p.id) AS comparative_link_count,
  (SELECT count(*) FROM lpm_divergence_reviews r WHERE r.project_id = p.id) AS divergences_reviewed,
  (SELECT count(*) FROM lpm_divergence_coverage c WHERE c.project_id = p.id AND c.is_stale) AS divergences_stale,
  (SELECT count(*) FROM lpm_data_objects o WHERE o.project_id = p.id AND o.object_type = 'substrand' AND o.status = 'draft') AS draft_substrand_count,
  (SELECT count(*) FROM lpm_threads th WHERE th.project_id = p.id AND th.status = 'proposed') AS proposed_strand_count
FROM projects p;

-- 1. Introduction text, shown on the project Dashboard. Plain TEXT; paragraphs split on blank lines.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS introduction TEXT;
COMMENT ON COLUMN projects.introduction IS 'Editable introduction shown at the top of the project Dashboard. Opens with status, then aim. Paragraphs are separated by blank lines.';
UPDATE projects SET introduction = $J$Status: synthetic. Nobody has taught from this space, AI drafted it from published research, and no subject-matter expert has reviewed it. Use it to compare designs and test ideas. Do not use it to plan lessons.

Bio-Core is a thought experiment about the narrowest useful way to teach evolution. It contains biology only, and only the ideas that explain evolution as variation, inheritance and selection acting on populations. It has no concepts about what organisms want or try to do. That omission is the design. The question it asks is how far a strictly population-level vocabulary can carry a student from kindergarten to grade 12.

Its partner space, Interdisciplinary, starts from the opposite assumption. The two were built to disagree so that their differences can be studied. Open them side by side in the Comparison view.

What is here: 3 strands (Variation and Inheritance, Natural Selection and Adaptation, Speciation and Diversity of Life), 12 stages across four grade bands, 35 learning outcomes and 15 concepts. Ten draft stages add human examples, one thread per strand. They are proposals that wait for expert review. Time is left open on purpose: nothing here assumes a number of hours.$J$ WHERE id = '28997544-0d87-4b05-9ee2-7c474513c108' AND introduction IS NULL;
UPDATE projects SET introduction = $J$Status: synthetic. Nobody has taught from this space, AI drafted it from published research, and no subject-matter expert has reviewed it. Its central claim, that an agency-inclusive progression supports better reasoning about causes, has less published testing behind it than Bio-Core's. Use it to compare designs and test ideas. Do not use it to plan lessons.

Interdisciplinary is a thought experiment about the widest useful way to teach evolution. It treats evolution as one general pattern (variation, selection, transmission) that shows up in living things, human culture, learning and technology, and it spreads that pattern across biology, social studies and computer science. It includes ideas about agency, teaching, niche construction and cooperation, and asks students to judge when thinking in terms of goals and choices explains something and when it misleads. The question it asks is whether meeting one pattern in several subjects builds flexible reasoning about causes.

Its partner space, Bio-Core, starts from the opposite assumption. The two were built to disagree so that their differences can be studied. Open them side by side in the Comparison view.

What is here: 4 strands (Inheritance, Variation and Selection Across Systems; Agency, Development and Niche Construction; Culture, Technology and Collective Systems; Discovering and Testing Ideas), 16 stages across four grade bands, 54 learning outcomes and 28 concepts. Eight draft stages add six cross-strand human-example bridge cases, one thread per case. They are proposals that wait for expert review. Time is left open on purpose: nothing here assumes a number of hours.$J$ WHERE id = '371fce26-d1f3-439b-95df-0a0e38b8a824' AND introduction IS NULL;

