-- 6. Comparative links between matching cases (relation_type distinct per pair).
INSERT INTO lpm_comparative_links (id, from_data_object_id, to_data_object_id, relation_type, divergence_ref, commentary)
VALUES
('0ecb8056-b513-5286-9d0c-3afe00fab17f', '45d9e1c6-4a42-51d6-8143-87c8b4433dda', '3be1a616-2c22-560e-9b08-5e5e3764f6fc', 'contrasting_treatment', NULL, 'Both spaces teach lactase persistence at 9-12. The biology is the same in both. What differs is which causes are in scope. Bio-Core treats it as an allele-frequency pattern explained by selection pressure, drift and migration, with nobody choosing anything. Interdisciplinary adds the cultural practice of dairying as a cause that changes the selection pressure, so Selection, Niche Construction and Culture are taught together in one case.'),
('832a63f1-f410-5d60-a490-e4eebd3b624d', '4a5998c8-7e4d-5508-b00b-a02527021ac5', 'bfb2d9bf-b765-5f7c-abc5-ef9d44f67247', 'contrasting_domestication', NULL, 'Both spaces use domestication. Bio-Core treats it as a selection pressure set by human choice, the same mechanism as natural selection with a different selector. Interdisciplinary treats it as two-way change: people alter the animals and plants, and those species alter how people live. The first case teaches one mechanism cleanly. The second links three concepts across strands.')
ON CONFLICT (id) DO NOTHING;

